# Read the three ICS files and extract VEVENT blocks and basic metadata (DTSTART/DTEND/SUMMARY/UID).
import re, json, os

paths = {
    "alice": "/app/alice_calendar.ics",
    "bob": "/app/bob_calendar.ics",
    "carol": "/app/carol_calendar.ics"
}

calendars_data = {}
for name, path in paths.items():
    if not os.path.exists(path):
        calendars_data[name] = {"exists": False, "path": path}
        continue
    with open(path, "r", encoding="utf-8") as f:
        ics = f.read()
    vevents = re.findall(r'BEGIN:VEVENT.*?END:VEVENT', ics, flags=re.DOTALL)
    parsed = []
    for ev in vevents:
        dtstart = re.search(r'DTSTART(?:;[^:]*)?:(.+)', ev)
        dtend = re.search(r'DTEND(?:;[^:]*)?:(.+)', ev)
        uid = re.search(r'UID:(.+)', ev)
        summary = re.search(r'SUMMARY:(.+)', ev)
        parsed.append({
            "raw": ev.strip(),
            "DTSTART": dtstart.group(1).strip() if dtstart else None,
            "DTEND": dtend.group(1).strip() if dtend else None,
            "UID": uid.group(1).strip() if uid else None,
            "SUMMARY": summary.group(1).strip() if summary else None,
            "char_len": len(ev)
        })
    calendars_data[name] = {
        "exists": True,
        "path": path,
        "full_ics_len": len(ics),
        "vevent_count": len(parsed),
        "vevents_parsed": parsed
    }

# Print concise summary for inspection (counts and first 2 events per calendar)
